const raw = $input.first().json || {};
if (raw.body) {
  const expected = $env.N8N_CALENDAR_TOKEN;
  const auth = raw.headers?.authorization || raw.headers?.Authorization || '';
  if (!expected || auth !== `Bearer ${expected}`) throw new Error('AUTH_FAILED: agenda local requiere bearer valido del VPS.');
}
const inp = raw.body || raw;
const confirmado = String(inp.confirmado_por_owner || '').toLowerCase() === 'true';
if (!confirmado) throw new Error('CONFIRMACION_REQUERIDA: agendar escribe en el calendario real de Alek. Manda la tarjeta al owner y vuelve con confirmado_por_owner=true.');
const inicio = String(inp.inicio_iso || '').trim();
const fin = String(inp.fin_iso || '').trim();
if (!inicio || !fin) throw new Error('FALTAN_HORARIOS: inicio_iso y fin_iso son obligatorios, en ISO 8601 UTC.');
if (Number.isNaN(Date.parse(inicio)) || Number.isNaN(Date.parse(fin))) throw new Error('HORARIO_INVALIDO: usa ISO 8601, por ejemplo 2026-08-22T15:00:00.000Z');
if (Date.parse(fin) <= Date.parse(inicio)) throw new Error('RANGO_INVALIDO: el fin va despues del inicio.');
const alfabeto = 'abcdefghijkmnpqrstuvwxyz23456789';
let token = '';
for (let i = 0; i < 20; i += 1) token += alfabeto[Math.floor(Math.random() * alfabeto.length)];
const nombre = String(inp.nombre_contacto || 'Lead IA360').trim();
const numero = String(inp.numero_contacto || '').replace(/[^0-9]/g, '');
const titulo = String(inp.titulo || '').trim() || ('Reunion IA360 - ' + nombre);
return [{ json: { token, start: inicio, end: fin, summary: titulo, contact: { contactName: nombre, contactNumber: numero }, contactName: nombre, contactNumber: numero } }];

const prep = $('Preparar Reserva').first().json;
const reserva = $('Reservar Calendar y Zoom').first().json || {};
const tz = 'America/Mexico_City';
const inicio = new Intl.DateTimeFormat('es-MX', { timeZone: tz, dateStyle: 'full', timeStyle: 'short' }).format(new Date(prep.start));
return [{ json: { ok: true, estado: 'agendada', token: prep.token, enlace_estable: 'https://wa.geekstudio.dev/api/r/' + prep.token, evento_id: reserva.calendarEventId || null, zoom: reserva.zoomJoinUrl || null, inicio_utc: prep.start, fin_utc: prep.end, inicio_local: inicio, titulo: prep.summary, resumen: 'Cita agendada: ' + prep.summary + ' — ' + inicio + ' (hora del centro de Mexico).' } }];

const raw = $input.first() ? ($input.first().json || {}) : {};
const detalle = raw.message || raw.error || JSON.stringify(raw).slice(0, 300);
return [{ json: { ok: false, estado: 'no_agendada', motivo: detalle || 'El webhook de reserva no devolvio un evento de Calendar.', que_hacer: 'No reintentes en automatico: reporta el error textual a Alek. Si el hueco estaba ocupado el mensaje dira slot_busy.' } }];
